UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Datteln mit Erdnussbutter'), description_de = COALESCE(description_de, 'Ein energiespendender Snack, der schmeckt, als würdest du echte Karamellschokolade essen.

