UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Sonne der Toskana'), description_de = COALESCE(description_de, 'Eine leichte und gesunde Variante des berühmten italienischen Gerichts „Melanzane alla Parmigiana“ – ganz ohne Anbraten.

