UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Protein-Bowl mit Hähnchen und Quinoa
(ab 9 Monaten)'), description_de = COALESCE(description_de, 'Eine lang anhaltende Energiequelle für Babys, die zunehmend aktiver werden und bereits krabbeln.

Vorteil: Hähnchenfleisch ist eine hochwertige Proteinquelle. Quinoa ist ein glutenfreies Superfood und zählt zu den nährstoffreichsten Getreidealternativen.'), category_de = COALESCE(category_de, 'Beikost'), tags_de = COALESCE(tags_de, ARRAY['babynahrung']::text[]), ingredients_de = COALESCE(ingredients_de, '["Hähnchenbrust: 30 g","Zucchini: Etwas weniger als eine halbe","Quinoa: 1 Esslöffel (vorher eingeweicht und gewaschen)."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Koche das Hähnchen und gieße das erste Kochwasser ab. Gib Quinoa und klein geschnittene Zucchini in frisches Wasser und koche alles, bis es vollständig weich ist. Püriere die Mischung anschließend im Mixer oder zerdrücke sie mit einer Gabel, sodass eine leicht stückige Konsistenz entsteht."]'::jsonb) WHERE id = '45628e71-5b41-431f-b26f-8283c2b308a2';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Knusprige Fischstäbchen (ab 2 Jahren)'), description_de = COALESCE(description_de, 'Die ungebratene, 100% natürliche Variante von tiefgekühlten Fischstäbchen aus dem Supermarkt.

Vorteil: Fisch liefert Omega-3-Fettsäuren, die für die Entwicklung von Gehirn und Augen des Babys unverzichtbar sind.'), category_de = COALESCE(category_de, 'Beikost'), tags_de = COALESCE(tags_de, ARRAY['baby_food']::text[]), ingredients_de = COALESCE(ingredients_de, '["Weißfischfilet (z. B. Wolfsbarsch – grätenfrei): 100 qr (in längliche Stücke geschnitten)","Ei: 1 Stück (verquirlt)","Hafermehl (zum Panieren)","Olivenöl, etwas Salz."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Die Fischstücke zuerst im Ei und anschließend im Hafermehl wenden.","Auf ein mit Backpapier ausgelegtes Backblech legen und mit sehr wenig Olivenöl bestreichen.","Bei 190 Grad 15 Minuten backen, bis sie knusprig sind."]'::jsonb) WHERE id = 'cf74a166-77b4-4cd9-978f-5f84fbaf4d6d';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Superman-Quesadilla (ab 5 Jahren)'), description_de = COALESCE(description_de, 'Ein mexikanischer Leckerbissen voller verstecktem Gemüse, den Kinder gern mit den Händen essen.

Vorteil: Schwarze Bohnen und Hähnchen liefern hochwertiges Eiweiß, während Käse reich an knochenstärkendem Kalzium ist.'), category_de = COALESCE(category_de, 'Beikost'), tags_de = COALESCE(tags_de, ARRAY['baby_food']::text[]), ingredients_de = COALESCE(ingredients_de, '["Vollkorn-Lawasch (Tortilla): 1 Stück","Holländischer Käse (gerieben): 2 Esslöffel","Schwarze Bohnen (gekocht) und Mais: 1 Esslöffel","Gezupftes Hähnchenfleisch: 1 Esslöffel","Spinat (sehr fein gehackt): Einige Blätter."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Käse, Hähnchenfleisch, Bohnen, Mais und Spinat auf einer Hälfte des Lawasch verteilen. Die andere Hälfte darüberklappen, sodass ein Halbmond entsteht. In einer heißen Pfanne von beiden Seiten braten, bis der Käse geschmolzen und der Lawasch knusprig ist. In Dreiecke schneiden und servieren."]'::jsonb) WHERE id = '495abf5b-aca7-4840-8cc2-c8a7f267da78';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Süßkartoffel-Linsen-Curry'), description_de = COALESCE(description_de, 'Ein veganer und glutenfreier Klassiker der indischen Küche, vollgepackt mit entzündungshemmenden Gewürzen.

Vorteil: Curry und Kurkuma unterstützen das Immunsystem, während die Süßkartoffel dem Gericht eine natürliche, samtige Süße verleiht.'), category_de = COALESCE(category_de, 'general'), tags_de = COALESCE(tags_de, ARRAY['general']::text[]), ingredients_de = COALESCE(ingredients_de, '["Süßkartoffel: 1 großes Stück (gewürfelt)","Rote Linsen: 1 Glas","Kokosmilch (die dickflüssige aus der Dose): 1 Glas","Currypulver: 1 Esslöffel","Spinat: 1 Handvoll."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Zwiebel, Knoblauch und Currypulver in Öl anbraten. Süßkartoffel, Linsen, Kokosmilch und 2 Gläser Wasser dazugeben. Bei niedriger Hitze köcheln lassen, bis das Gemüse vollständig gar ist. Vom Herd nehmen, den Spinat dazugeben und unterrühren."]'::jsonb) WHERE id = '405b0576-a236-4ed8-8698-3423fb1d2ff0';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Sternennacht-Suppe (ab 3 Jahren)'), description_de = COALESCE(description_de, 'Eine köstliche Knochenbrühe mit darin schwimmenden Sternchen – für Kinder, die sonst keine Suppe mögen.

Vorteil: Knochenbrühe ist reich an Kollagen und Kalzium und unterstützt das Wachstum sowie starke Knochen bei Kindern.'), category_de = COALESCE(category_de, 'Beikost'), tags_de = COALESCE(tags_de, ARRAY['Babynahrung']::text[]), ingredients_de = COALESCE(ingredients_de, '["Klare Knochen- oder Hühnerbrühe: 2 Tassen","Sternchen-Nudeln für Babys: 2 Esslöffel","Karotte: Eine halbe (in sehr kleine Sternchen geschnitten)","Petersilie: Sehr wenig (zum Garnieren)."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Die Brühe zum Kochen bringen und die Sternchen-Nudeln sowie die sternförmig geschnittenen Karotten dazugeben. Kochen, bis die Nudeln vollständig weich sind (etwa 8-10 Minuten)."]'::jsonb) WHERE id = '60680ede-d11d-4b46-a277-695525f7d111';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Matcha Strawberry Cloud'), description_de = COALESCE(description_de, 'Das Trendgetränk aus den sozialen Netzwerken. Eine echte Antioxidantienbombe, die die Haut mit wertvollen Nährstoffen versorgt.'), category_de = COALESCE(category_de, 'Gesunde Getränke'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["1 Teelöffel Matcha-Pulver (in lauwarmem Wasser aufgelöst), 4-5 frische Erdbeeren (zu Püree zerdrückt), 1 Tasse Mandelmilch, Eis."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Das Erdbeerpüree auf den Boden des Glases geben, anschließend Eis und Milch hinzufügen. Zum Schluss den aufgelösten grünen Matcha langsam hineingießen, damit die Farbschichten erhalten bleiben (unten rosa, oben grün)."]'::jsonb) WHERE id = '40f5ac74-8479-42d8-bab7-5b56e15de9ae';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Mandel-Pancakes mit Chia-Konfitüre'), description_de = COALESCE(description_de, 'Die gluten- und zuckerfreie „Healthy-Lifestyle“-Alternative zu Pancakes aus herkömmlichem Mehl.

Vorteil: Mandelmehl lässt den Blutzuckerspiegel nicht schlagartig ansteigen (niedriger glykämischer Index). Mit Chia-Konfitüre kannst du außerdem auf den Zucker in industriell hergestellten Konfitüren verzichten.'), category_de = COALESCE(category_de, 'Allgemein'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Mandelmehl: 1 Tasse","Eier: 2 Stück","Mandelmilch: Eine viertel Tasse","Für die Konfitüre: 1 Tasse tiefgekühlte Himbeeren und 2 Esslöffel Chiasamen."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Die Himbeeren erwärmen und zerdrücken, die Chiasamen unterrühren und die Mischung abkühlen (und eindicken) lassen. Währenddessen Mandelmehl, Eier und Milch verquirlen und in einer Pfanne kleine Pancakes backen. Mit der selbst gemachten zuckerfreien Chia-Konfitüre servieren."]'::jsonb) WHERE id = '0d809ddc-e476-418c-9f34-67e7b608cf9f';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Indisches Linsenpüree'), description_de = COALESCE(description_de, 'Ein Liebling der vegetarischen Küche: ein goldener indischer Eintopf, der den Körper mit der Kraft seiner Gewürze von innen wärmt.

Vorteil: Kurkuma und Ingwer wirken entzündungshemmend. Linsen liefern pflanzliches Eiweiß und halten lange satt.'), category_de = COALESCE(category_de, 'Allgemein'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Rote oder gelbe Linsen: 1 Tasse","Zwiebel, Knoblauch, frischer Ingwer.","Kurkuma und Currypulver: jeweils 1 Teelöffel.","Tomate: 1 Stück","Kokosmilch: sehr wenig (zum Garnieren)."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Zwiebel, Knoblauch, Ingwer und Gewürze in Öl anbraten, bis sie duften. Die gewürfelte Tomate und die Linsen dazugeben. Wasser hinzufügen und kochen, bis die Linsen vollständig zerfallen sind und eine püreeartige Konsistenz haben. Mit etwas Kokosmilch und Koriander garnieren."]'::jsonb) WHERE id = 'f1edbb7c-89ad-49b8-9c59-42461d445810';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Deutscher Kartoffelsalat'), description_de = COALESCE(description_de, 'Ein herrlich leichter deutscher Salat mit Senf und Essig, der ganz ohne schwere Mayonnaise auskommt.

Vorteil: Beim Abkühlen bildet sich in Kartoffeln präbiotische „resistente Stärke“, die gut für den Darm ist. Da der Salat keine Mayonnaise enthält, ist er zudem cholesterinärmer.'), category_de = COALESCE(category_de, 'Allgemein'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Kartoffeln: 3-4 Stück (gekocht, abgekühlt und in Scheiben geschnitten)","Rote Zwiebel: 1 kleine (fein gehackt)","Frische Petersilie oder frischer Dill","Für das Dressing: 1 Esslöffel körniger Senf, 2 Esslöffel Apfelessig, 3 Esslöffel Olivenöl, Salz, schwarzer Pfeffer."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Zwiebel und Kräuter über die lauwarmen oder vollständig abgekühlten Kartoffelscheiben geben. Senf, Essig und Öl in einem Glas gut schütteln, bis ein Dressing entsteht, und dieses unter den Salat mischen."]'::jsonb) WHERE id = 'bfa226ee-4fae-4a95-b348-aee056cab96b';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Shrek''s Mac & Cheese (ab 3 Jahren)'), description_de = COALESCE(description_de, 'Käsenudeln in einer auffällig schönen grünen Farbe, in deren Sauce sich Spinat versteckt.

Vorteil: Viele 3-jährige Kinder möchten Spinat weder roh noch gekocht essen. Mit dieser Sauce nehmen sie ganz unbemerkt eine gute Portion Eisen zu sich.'), category_de = COALESCE(category_de, 'Beikost'), tags_de = COALESCE(tags_de, ARRAY['baby_food']::text[]), ingredients_de = COALESCE(ingredients_de, '["Nudeln: 1 Tasse","Spinat: 1 große Handvoll","Milch: eine halbe Tasse","Mozzarella oder Gouda: 2 Esslöffel (gerieben)."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Die Nudeln kochen und abgießen. Spinat und Milch im Mixer zu einer vollkommen grünen, glatten Flüssigkeit pürieren. Diese grüne Milch in eine heiße Pfanne geben, den Käse hinzufügen und schmelzen lassen. Zum Schluss die Nudeln dazugeben und alles gründlich vermischen."]'::jsonb) WHERE id = '82a7ccbd-e708-435c-afe7-61fd5589966e';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Peruanische Ceviche'), description_de = COALESCE(description_de, 'Ein erfrischendes, proteinreiches Rezept aus Lateinamerika, bei dem der Fisch ganz ohne Hitze nur durch die Säure von Zitrusfrüchten „gegart“ wird.

Vorteil: Kein zusätzliches Fett und ein Maximum an hochwertigem Protein. Ein besonders beliebtes Gericht bei Menschen, die auf ihre Ernährung achten.'), category_de = COALESCE(category_de, 'Allgemein'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Weißfischfilet (sehr frisch und grätenfrei): 200 qr (in kleine Würfel geschnitten)","Limettensaft: eine halbe Tasse (frisch gepresst)","Rote Zwiebel: eine halbe (in dünne Halbmonde geschnitten)","Frischer Koriander, scharfe Jalapeño (nach Belieben), Salz."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Die rohen Fischwürfel in eine Glasschüssel geben und mit Limettensaft und etwas Salz übergießen. Der Saft lässt den Fisch weiß werden und „gart“ ihn. 20-30 Minuten im Kühlschrank ziehen lassen. Kurz vor dem Servieren Zwiebel und Koriander hinzufügen und alles vermischen."]'::jsonb) WHERE id = '53cbba9d-f39f-4a00-950a-386243d164bd';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Skandinavisches Smørrebrød'), description_de = COALESCE(description_de, 'Die aus Dänemark und Norwegen stammende Kunst des offenen Sandwiches auf dunklem Roggenbrot.

Vorteil: Roggenbrot liefert komplexe Kohlenhydrate und lässt den Blutzucker nicht sprunghaft ansteigen. Lachs wiederum ist reich an Omega-3-Fettsäuren, die als eines der Geheimnisse der skandinavischen Langlebigkeit gelten.'), category_de = COALESCE(category_de, 'Allgemein'), ingredients_de = COALESCE(ingredients_de, '["Dunkles Roggenvollkornbrot: 1 große Scheibe","Frischkäse (Labneh): 1 Esslöffel","Geräucherter oder gebeizter Lachs: 2-3 Scheiben","Rote Zwiebelringe, frischer Dill, Radieschenscheiben."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Den Frischkäse auf das Brot streichen. Die Lachsscheiben wellenförmig darauf anrichten. Mit Zwiebelringen, dünn geschnittenen Radieschen und reichlich Dill garnieren und ansprechend servieren."]'::jsonb) WHERE id = 'dded217d-3179-4368-8e13-255ed13ea4cf';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Quinoa-Taboulé (libanesische Küche)'), description_de = COALESCE(description_de, 'Ein beliebter Salat aus dem Nahen Osten, bei dem der traditionelle Bulgur durch glutenfreie und proteinreichere Quinoa ersetzt wird.

Vorteil: Leicht, ballaststoffreich und dank der großen Menge Petersilie eine hervorragende Vitamin-C-Quelle. Hilft, den Blutzuckerspiegel zu regulieren.'), category_de = COALESCE(category_de, 'Allgemein'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Quinoa (gekocht und abgekühlt): 1 Tasse","Frische Petersilie (sehr fein gehackt): 2 große Bund","Frische Minze: 1 kleiner Bund","Tomaten: 2 Stück (klein gewürfelt)","Frühlingszwiebeln: 3-4 Stängel","Natives Olivenöl extra und reichlich Zitronensaft, Salz."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Alle gehackten Kräuter und das Gemüse in einer tiefen Schüssel mit der gekochten Quinoa vermischen. Großzügig mit Olivenöl und Zitronensaft beträufeln und alles gründlich vermengen. Mindestens 30 Minuten im Kühlschrank durchziehen lassen."]'::jsonb) WHERE id = '23f9812f-031f-4161-95cf-ce2d96da0985';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Blumenkohl nach Buffalo-Art'), description_de = COALESCE(description_de, 'Eine 100% vegetarische und gesunde Alternative zum berühmten amerikanischen Gericht „Buffalo Wings“ (Hähnchenflügel).

Vorteil: Stillt die Lust auf knuspriges Fast Food, verwendet aber ballaststoffreichen Blumenkohl statt Hähnchen und den Backofen statt der Fritteuse.'), category_de = COALESCE(category_de, 'Allgemein'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Blumenkohl: 1 Kopf (in Röschen geteilt)","Vollkornmehl und Wasser: Für den Teig (mit der Konsistenz von Pfannkuchenteig)","Scharfe Buffalo-Sauce (oder eine Mischung aus einer beliebigen scharfen Sauce und Butter)."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Die Blumenkohlröschen in die Mehl-Wasser-Mischung tauchen und auf einem Backblech verteilen. Bei 200 Grad 20 Minuten backen. Herausnehmen, mit der scharfen Sauce beträufeln und weitere 10 Minuten backen, bis die Ränder knusprig sind."]'::jsonb) WHERE id = '287fe4e5-acde-487e-8549-304293001ae7';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Andalusian Breeze – Spanische Gazpacho'), description_de = COALESCE(description_de, 'Eine erfrischende, rohe und vitaminreiche Tomatensuppe aus Südspanien, die ganz ohne Kochen zubereitet wird.

Vorteil: Ein reiner „Blüten- und Gemüse“-Detox. Dank Lycopin (Tomaten) und Vitamin C (Paprika) schützt sie die Haut von innen vor schädlicher Sonnenstrahlung.'), category_de = COALESCE(category_de, 'Allgemein'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Sehr reife, rote Tomaten: 4-5 Stück","Gurke: 1 Stück (gekühlt)","Grüne Paprika: Eine halbe","Rote Zwiebel und Knoblauch (sehr wenig)","Natives Olivenöl extra (2 Esslöffel) und Apfelessig (1 Esslöffel)."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Alle Zutaten in den Mixer geben, Olivenöl, Essig und etwas Salz hinzufügen und mixen, bis eine vollständig flüssige Suppe entsteht. Mindestens 2 Stunden im Kühlschrank aufbewahren, bis sie eiskalt ist."]'::jsonb) WHERE id = '0732d705-b1b2-4b26-b8dc-748f80e0f06a';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Gold Mac & Cheese (ab 2 Jahren)'), description_de = COALESCE(description_de, 'Eine besonders gesunde Variante der bei Kindern beliebten Käsenudeln, in der sich Gemüse versteckt.

Vorteil: Statt einer klassischen Sauce aus Mehl und Fett bilden Kürbis und Karotten die Grundlage. Das Gericht ist reich an Vitamin A und Kalzium.'), category_de = COALESCE(category_de, 'Beikost'), tags_de = COALESCE(tags_de, ARRAY['Babynahrung']::text[]), ingredients_de = COALESCE(ingredients_de, '["Vollkornnudeln (Hörnchen oder Spiralen): 1 Tasse","Kürbis und Karotten (gekocht): Je eine halbe Tasse","Milch: Eine halbe Tasse","Cheddar oder holländischer Käse: 3 Esslöffel, gerieben"]'::jsonb), instructions_de = COALESCE(instructions_de, '["Die Nudeln in Wasser vollständig gar kochen und abgießen.","Den gekochten Kürbis, die Karotten und die Milch im Mixer zu einer vollkommen glatten, orangefarbenen Creme (Sauce) pürieren.","Die Sauce in eine heiße Pfanne geben, den geriebenen Käse hinzufügen und schmelzen lassen. Zum Schluss die Nudeln unter die Sauce mischen."]'::jsonb) WHERE id = '6a513f71-83a0-47b7-94eb-0de33be5ff6d';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Kichererbsen-Blondie'), description_de = COALESCE(description_de, 'Ein karamelliger, mehlfreier Kuchen, bei dem niemand glauben wird, dass er Kichererbsen enthält.

Vorteil: Diese Süßigkeit liefert hochwertiges Eiweiß und komplexe Kohlenhydrate. Sie verursacht keine glutenbedingten Blähungen und passt nach dem abendlichen Training – zur Unterstützung der Muskelregeneration – hervorragend zu einer Tasse Tee.'), category_de = COALESCE(category_de, 'Gesunde Süßigkeiten'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Kichererbsen aus der Dose: 1 Tasse (gründlich abgespült und gehäutet)","Erdnussmus: 3 Esslöffel","Honig oder Ahornsirup: 3 Esslöffel","Vanille, Backpulver.","Zartbitter-Schokodrops."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Alle Zutaten außer der Schokolade im Mixer zu einem vollkommen glatten Teig pürieren. Die Schokodrops unterheben und den Teig in eine kleine quadratische Backform geben. Bei 175 Grad 20 Min. backen. Noch lauwarm in Stücke schneiden."]'::jsonb) WHERE id = '4b5bc08b-15b1-4187-aa19-05b7b3bb4ae4';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Rote-Linsen-Ingwer-Suppe'), description_de = COALESCE(description_de, 'Ein wärmendes Wintermittagessen, das den Stoffwechsel in Schwung bringt.

Vorteile: Ingwer und Kurkuma können Entzündungsreaktionen im Körper (Schwellungen, Akne, Gelenkschmerzen) lindern, während rote Linsen lange satt halten.'), category_de = COALESCE(category_de, 'Mittagessen'), tags_de = COALESCE(tags_de, ARRAY['allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Rote Linsen: 1 Glas","Frischer Ingwer: haselnussgroß (gerieben)","Kurkuma: ein halber Teelöffel","Karotte, Zwiebel.","Kokosmilch: 2 Esslöffel (optional, als Topping)."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Koche das gesamte Gemüse und die Linsen in Wasser weich und püriere alles mit einem Mixer. Gib Kurkuma und Ingwer hinzu und lasse die Suppe noch etwas köcheln. Fülle sie in eine Schüssel und träufle Kokosmilch darüber."]'::jsonb) WHERE id = '9dca9acb-e3bc-495a-9af1-62c75bc63dca';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Süßkartoffel mit Bohnen'), description_de = COALESCE(description_de, 'Ein Rezept, das während des PMS (vor der Periode) helfen kann, Heißhunger auf Süßes und Stimmungsschwankungen auszugleichen.

Vorteile: Süßkartoffeln und schwarze Bohnen sind reich an Magnesium, unterstützen das Nervensystem, können Krämpfe lindern und halten lange satt.'), category_de = COALESCE(category_de, 'Mittagessen'), tags_de = COALESCE(tags_de, ARRAY['allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Süßkartoffel: 1 Stück (halbiert und im Ofen vollständig gegart)","Schwarze Bohnen (oder Kidneybohnen): 2 Esslöffel (gekocht)","Mais: 1 Esslöffel","Avocadocreme (Guacamole) und Limettensaft."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Fülle die weiche, gegarte Süßkartoffel mit schwarzen Bohnen und Mais. Gib Avocadocreme darauf und beträufle alles mit Limettensaft."]'::jsonb) WHERE id = '0298f702-76b2-4fe4-995b-506dab64f0f1';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Bärchen-Püree(1 Jahr+)'), description_de = COALESCE(description_de, 'Ein saftiges, zartschmelzendes Wintergericht für Kinder, denen das Kauen von Fleisch noch schwerfällt.

Vorteile: Lange gegartes Fleisch ist leicht verdaulich, und die nährstoffreiche Brühe unterstützt die Knochenentwicklung.'), category_de = COALESCE(category_de, 'Beikost'), tags_de = COALESCE(tags_de, ARRAY['baby_food']::text[]), ingredients_de = COALESCE(ingredients_de, '["Rindfleisch: 50 g (sehr kleine, erbsengroße Würfel)","Karotte und Kartoffel: je eine Hälfte (gewürfelt)","Tomate: ein Viertel (gerieben)","Olivenöl und Wasser."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Brate das Fleisch in Olivenöl an, bis es seine Farbe verändert. Gib die Tomate und Wasser hinzu und gare alles, bis das Fleisch weich ist (am besten im Schnellkochtopf). Füge anschließend Karotte und Kartoffel hinzu und lasse alles weitergaren, bis auch das Gemüse so weich ist, dass es sich zerdrücken lässt."]'::jsonb) WHERE id = 'a7eb16f8-9a88-4ac0-92d3-fb7d3da355e0';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Golden Glow Tonic'), description_de = COALESCE(description_de, 'Ein morgendliches Tonic, das Entzündungen im Körper lindert und wie ein Schutzschild gegen Krankheiten wirkt.

Vorteil: Kurkuma ist ein starkes natürliches entzündungshemmendes Mittel. Es kann Hautrötungen und Gelenkschmerzen lindern und der Haut ihren natürlichen Glow zurückgeben.'), category_de = COALESCE(category_de, 'Gesunde Getränke'), tags_de = COALESCE(tags_de, ARRAY['general']::text[]), ingredients_de = COALESCE(ingredients_de, '["Lauwarmes Wasser: 1 Glas","Kurkumapulver: Ein halber Teelöffel","Schwarzer Pfeffer: Eine Prise (unerlässlich, damit Kurkuma vom Körper aufgenommen werden kann)","Zitronensaft und 1 Teelöffel naturbelassener Apfelessig"]'::jsonb), instructions_de = COALESCE(instructions_de, '["Alle Zutaten gut vermischen und morgens lauwarm (so, dass Hals und Magen nicht gereizt werden) in kleinen Schlucken trinken."]'::jsonb) WHERE id = '55d6317c-4bcb-4a93-943a-dda17af68226';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Bunte Spieße (ab 5 Jahren)'), description_de = COALESCE(description_de, 'Bunte Spieße, die Gemüse und Fleisch gemeinsam wie ein farbenfrohes Spiel präsentieren.

