UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Zucchini-Spaghetti mit Pesto'), description_de = COALESCE(description_de, 'Eine wunderbare Pasta-Alternative, die den Genuss eines Nudelgerichts bietet, ohne dick zu machen.

Vorteil: Sie ist sehr kalorienarm. Olivenöl und Basilikum im Pesto sind starke Antioxidantien und helfen, die Zellen jung zu halten.'), category_de = COALESCE(category_de, 'Mittagessen'), tags_de = COALESCE(tags_de, ARRAY['general']::text[]), ingredients_de = COALESCE(ingredients_de, '["Zucchini: 2 mittelgroße (mit einem Spiralschneider wie Spaghetti geschnitten)","Pesto: 2 Esslöffel (aus frischem Basilikum, Olivenöl, Walnüssen und zerdrücktem Knoblauch)","Cherrytomaten: 4-5 Stück."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Die Zucchini-Spaghetti mit etwas Olivenöl nur 2-3 Minuten in der Pfanne anbraten (nicht zu lange garen, damit sie knackig bleiben). Vom Herd nehmen und mit dem Pesto und den halbierten Tomaten vermischen."]'::jsonb) WHERE id = '4562e352-5778-4e1f-951e-cc27bf63469a';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Brokkoli-Rindfleisch-Pfanne'), description_de = COALESCE(description_de, 'Einer der gesündesten Klassiker der beliebten asiatischen (chinesischen) Küche, der weltweit geschätzt wird.

Vorteil: Sorgt für eine hervorragende Balance aus Eisen (aus dem Fleisch) sowie Kalzium und Vitamin C (aus dem Brokkoli). Schnell zubereitet.'), category_de = COALESCE(category_de, 'Allgemein'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Rindfleisch (Filet, sehr dünn geschnitten): 250 qr","Brokkoli: 1 ganzer Kopf (in Röschen geteilt)","Sojasauce (salzarm): 3 Esslöffel","Frischer Ingwer und Knoblauch (zerdrückt).","Sesamöl und Sesamsamen."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Brate das Fleisch in einer Pfanne (Wok) bei hoher Hitze kurz und kräftig an und stelle es beiseite. Gib Brokkoli, Knoblauch und Ingwer in dieselbe Pfanne und brate alles 3-4 Minuten unter Rühren an (der Brokkoli sollte knackig bleiben). Gib das Fleisch zurück in die Pfanne, füge die Sojasauce hinzu und rühre alles 1 Minute lang um. Mit Sesam bestreuen und vom Herd nehmen."]'::jsonb) WHERE id = 'cdafe114-fffe-4d67-b795-0770d33715ea';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Cracker aus Leinsamen und Mandelmehl'), description_de = COALESCE(description_de, 'Hausgemachte, 100% glutenfreie und kohlenhydratfreie (Keto-)Cracker als Alternative zu ungesunden Chips aus dem Supermarkt.

Vorteil: Mandelmehl ist reich an Vitamin E, während Leinsamen die Darmtätigkeit hervorragend regulieren.'), category_de = COALESCE(category_de, 'Allgemein'), tags_de = COALESCE(tags_de, ARRAY['Allgemein']::text[]), ingredients_de = COALESCE(ingredients_de, '["Mandelmehl: 1 Tasse","Leinsamen (gemahlen): 3 Esslöffel","Wasser: 3 Esslöffel","Olivenöl: 1 Esslöffel","Salz und getrockneter Thymian."]'::jsonb), instructions_de = COALESCE(instructions_de, '["Verknete alle Zutaten in einer Schüssel zu einem Teig. Rolle ihn zwischen zwei Bögen Backpapier mit einem Nudelholz sehr dünn (wie Chips) aus. Schneide den Teig mit einem Messer in Quadrate und backe die Cracker bei 170 Grad 15-20 Minuten im Ofen, bis sie knusprig sind."]'::jsonb) WHERE id = 'd73926c7-3c66-41bd-88a6-1a28c3a2f959';
UPDATE public.admin_recipes SET title_de = COALESCE(title_de, 'Cacao Maca Magic'), description_de = COALESCE(description_de, 'Ein warmes Genusserlebnis, das die weiblichen Hormone ins Gleichgewicht bringt und die Glückshormone in die Höhe treibt.

